    const firstVisibleIndex: number | undefined = this.firstVisibleIndex();
    if (firstVisibleIndex === undefined) return false;

    const firstVisibleEntry: IntersectionObserverEntry | null = this.getVisibleEntry(firstVisibleIndex);
