      }

      onCleanup(() => {
        animation?.cancel();
        animation = null;
        controller.abort();
        // Only emit 'stopped' when autoplay has been disabled or the element is gone (final cleanup).
        // This prevents emitting 'stopped' on ordinary effect re-runs (e.g. when the active item changes)
        if (!this.autoplay()) {
          emitState('stopped');
        }
      });
    });
  }
}

