      const itemsPerView: number = this.galleryRef.itemsPerView();
      if (this.galleryRef.getPrevNavigationIndex(steps === 'page' ? itemsPerView : steps) === 0) {
        if (this.galleryRef.loop() && !this.galleryRef.hasPrev()) {
