gallery-debug {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 10;
  grid-area: center;
  pointer-events: none;

  &:after, &:before {
    pointer-events: none;
    position: absolute;
    content: '';
    z-index: 12;
  }

  &:before {
    width: 100%;
    height: 0;
    border-top: 1px dashed lime;
  }

