  }
}

gallery {
  .g-slider {

    slider-item {
      &.g-visible-item {
        &:after {
          content: '';
          position: absolute;
          width: 100%;
          height: 100%;
          border: 3px solid lime;
          box-sizing: border-box;
          z-index: 10;
        }
      }
    }
  }


  slider-item {
    &.g-anchor-item {
      &:after {
        content: '';
        position: absolute;
        width: 100%;
        height: 100%;
        border: 2px solid cyan;
        box-sizing: border-box;
        z-index: 11;
      }
    }

    &.g-active-item {
      &:after {
        pointer-events: none;
        content: '';
        position: absolute;
        width: 100%;
        height: 100%;
        border: 3px solid #E91E63;
        box-sizing: border-box;
        z-index: 11;
      }
    }
  }

  .g-sliding {
    .g-slider-sliding {
      display: block;
    }
  }

  .g-scrolling {
    .g-slider-scrolling {
      display: block;
    }
  }

  .g-resizing {
    .g-slider-resizing {
      display: block;
    }
  }

  .g-slider-observed {
    display: block !important;
  }

  .g-slider-debug {
    pointer-events: none;
    position: absolute;
    top: 0;
    left: 0;
    display: flex;
    gap: 5px;
    padding: 10px;

    .g-slider-resizing {
      background: rgba(245, 76, 40);
    }

    .g-slider-scrolling {
      background: rgb(255, 133, 36);
    }

    .g-slider-sliding {
      background: rgb(31, 108, 185);
    }

    .g-slider-observed {
      background: rgb(31, 185, 139);
    }

    div, &:before {
      display: none;
      color: white;
      font-family: monospace;
      z-index: 12;
      padding: 2px 6px;
      border-radius: 3px;
    }
  }

}

