              stroke="currentColor"
              stroke-width="2.5"
              stroke-linecap="round"
              stroke-linejoin="round"/>
      </svg>
    </ng-template>

    <div [gallerySlot]="prevSlot()"
         [gallerySlotAlign]="prevAlignSlot()"
         [gallerySlotJustify]="prevJustifySlot()"
